        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            try
            {
                var update = new ShipmentDto { Status = newStatus };
                var response = await Http.PutAsJsonAsync($"/api/shipments/{shipment.Id}", update);
                if (response.IsSuccessStatusCode)
                {
                    await LoadShipments();
                }
                else
                {
                    errorMessage = "Failed to update shipment status.";
                }
            }
            catch (Exception ex)
