    private string? errorMessage;
    private string? successMessage;
    private bool isSubmitting;

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        errorMessage = null;
        successMessage = null;

        try
        {
            var response = await Http.PostAsJsonAsync("/api/shipments", model);
            if (response.IsSuccessStatusCode)
            {
                var created = await response.Content.ReadFromJsonAsync<ShipmentDto>();
                successMessage = $"Shipment created! Tracking number: {created?.TrackingNumber}";
                model = new ShipmentDto { EstimatedDelivery = DateTime.Today.AddDays(7) };
            }
            else
            {
                errorMessage = "Failed to create shipment. Please try again.";
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Error creating shipment: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

