+@page "/track-shipment"
+@rendermode InteractiveAuto
+@using Microsoft.AspNetCore.Authorization
+@attribute [Authorize]
+@inject HttpClient Http
+
+<PageTitle>Track Shipment</PageTitle>
+
+<h3 class="mb-4">Track Your Shipment</h3>
+
+<div class="row mb-4">
+    <div class="col-md-6">
+        <div class="input-group">
+            <input type="text" class="form-control" placeholder="Enter tracking number..."
+                   @bind="trackingNumber" @bind:event="oninput"
+                   @onkeydown="HandleKeyDown" />
+            <button class="btn btn-primary" @onclick="TrackShipmentAsync" disabled="@isLoading">
+                @if (isLoading)
+                {
+                    <span class="spinner-border spinner-border-sm" role="status"></span>
+                }
+                else
+                {
+                    <span>Track</span>
+                }
+            </button>
+        </div>
+    </div>
+</div>
+
+@if (errorMessage is not null)
+{
+    <div class="alert alert-danger">@errorMessage</div>
+}
+
+@if (shipment is not null)
+{
+    <div class="card">
+        <div class="card-header">
+            <h5 class="mb-0">Shipment: <code>@shipment.TrackingNumber</code></h5>
+        </div>
+        <div class="card-body">
+            <div class="row mb-4">
+                <div class="col-md-6">
+                    <p><strong>Origin:</strong> @shipment.Origin</p>
+                    <p><strong>Destination:</strong> @shipment.Destination</p>
+                    <p><strong>Description:</strong> @shipment.Description</p>
+                </div>
+                <div class="col-md-6">
+                    <p><strong>Status:</strong> <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span></p>
+                    <p><strong>Created:</strong> @shipment.CreatedAt.ToString("MMM dd, yyyy")</p>
+                    <p><strong>Estimated Delivery:</strong> @(shipment.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "N/A")</p>
+                    @if (shipment.ActualDelivery.HasValue)
+                    {
+                        <p><strong>Delivered On:</strong> @shipment.ActualDelivery.Value.ToString("MMM dd, yyyy")</p>
+                    }
+                </div>
+            </div>
+
+            <!-- Status Timeline -->
+            <h6>Shipment Progress</h6>
+            <div class="progress mb-2" style="height: 25px;">
+                <div class="progress-bar @GetProgressBarClass(shipment.Status)"
+                     role="progressbar"
+                     style="width: @GetProgressPercentage(shipment.Status)%"
+                     aria-valuenow="@GetProgressPercentage(shipment.Status)"
+                     aria-valuemin="0"
+                     aria-valuemax="100">
+                    @shipment.Status
+                </div>
+            </div>
+            <div class="d-flex justify-content-between text-muted small">
+                <span>Pending</span>
+                <span>Picked Up</span>
+                <span>In Transit</span>
+                <span>Out for Delivery</span>
+                <span>Delivered</span>
+            </div>
+        </div>
+    </div>
+}
+
+@code {
+    private string trackingNumber = string.Empty;
+    private ShipmentDto? shipment;
+    private string? errorMessage;
+    private bool isLoading;
+
+    private async Task HandleKeyDown(KeyboardEventArgs e)
+    {
+        if (e.Key == "Enter")
+        {
+            await TrackShipmentAsync();
+        }
+    }
+
+    private async Task TrackShipmentAsync()
+    {
+        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
+
+        isLoading = true;
+        errorMessage = null;
+        shipment = null;
+
+        try
+        {
+            var response = await Http.GetAsync($"/api/shipments/{Uri.EscapeDataString(trackingNumber.Trim())}");
+            if (response.IsSuccessStatusCode)
+            {
+                shipment = await response.Content.ReadFromJsonAsync<ShipmentDto>();
+            }
+            else if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
+            {
+                errorMessage = "Shipment not found. Please check the tracking number and try again.";
+            }
+            else
+            {
+                errorMessage = "Unable to retrieve shipment information. Please try again later.";
+            }
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Error tracking shipment: {ex.Message}";
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
+    {
+        ShipmentStatus.Pending => "bg-secondary",
+        ShipmentStatus.PickedUp => "bg-info",
+        ShipmentStatus.InTransit => "bg-primary",
+        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
+        ShipmentStatus.Delivered => "bg-success",
+        ShipmentStatus.Cancelled => "bg-danger",
+        _ => "bg-secondary"
+    };
+
+    private static string GetProgressBarClass(ShipmentStatus status) => status switch
+    {
+        ShipmentStatus.Cancelled => "bg-danger",
+        ShipmentStatus.Delivered => "bg-success",
+        _ => "bg-primary"
+    };
+
+    private static int GetProgressPercentage(ShipmentStatus status) => status switch
+    {
+        ShipmentStatus.Pending => 10,
+        ShipmentStatus.PickedUp => 30,
+        ShipmentStatus.InTransit => 55,
+        ShipmentStatus.OutForDelivery => 80,
+        ShipmentStatus.Delivered => 100,
+        ShipmentStatus.Cancelled => 100,
+        _ => 0
+    };
+}
+

