+@page "/create-shipment"
+@rendermode InteractiveAuto
+@using Microsoft.AspNetCore.Authorization
+@attribute [Authorize(Roles = "Dispatcher")]
+@inject HttpClient Http
+@inject NavigationManager Navigation
+
+<PageTitle>Create Shipment</PageTitle>
+
+<h3 class="mb-4">Create New Shipment</h3>
+
+@if (successMessage is not null)
+{
+    <div class="alert alert-success">@successMessage</div>
+}
+
+@if (errorMessage is not null)
+{
+    <div class="alert alert-danger">@errorMessage</div>
+}
+
+<div class="row">
+    <div class="col-md-8">
+        <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="CreateShipmentForm">
+            <DataAnnotationsValidator />
+            <ValidationSummary class="text-danger" />
+
+            <div class="mb-3">
+                <label for="origin" class="form-label">Origin</label>
+                <InputText id="origin" class="form-control" @bind-Value="model.Origin" placeholder="e.g. New York, NY" />
+                <ValidationMessage For="() => model.Origin" class="text-danger" />
+            </div>
+
+            <div class="mb-3">
+                <label for="destination" class="form-label">Destination</label>
+                <InputText id="destination" class="form-control" @bind-Value="model.Destination" placeholder="e.g. Los Angeles, CA" />
+                <ValidationMessage For="() => model.Destination" class="text-danger" />
+            </div>
+
+            <div class="mb-3">
+                <label for="customerEmail" class="form-label">Customer Email</label>
+                <InputText id="customerEmail" class="form-control" @bind-Value="model.CustomerEmail" placeholder="customer@example.com" />
+                <ValidationMessage For="() => model.CustomerEmail" class="text-danger" />
+            </div>
+
+            <div class="mb-3">
+                <label for="description" class="form-label">Description</label>
+                <InputTextArea id="description" class="form-control" @bind-Value="model.Description" rows="3" placeholder="Package description..." />
+                <ValidationMessage For="() => model.Description" class="text-danger" />
+            </div>
+
+            <div class="mb-3">
+                <label for="estimatedDelivery" class="form-label">Estimated Delivery</label>
+                <InputDate id="estimatedDelivery" class="form-control" @bind-Value="model.EstimatedDelivery" />
+            </div>
+
+            <button type="submit" class="btn btn-primary" disabled="@isSubmitting">
+                @if (isSubmitting)
+                {
+                    <span class="spinner-border spinner-border-sm" role="status"></span>
+                    <span> Creating...</span>
+                }
+                else
+                {
+                    <span>Create Shipment</span>
+                }
+            </button>
+            <a href="/shipments" class="btn btn-secondary ms-2">Cancel</a>
+        </EditForm>
+    </div>
+</div>
+
+@code {
+    [SupplyParameterFromForm]
+    private ShipmentDto model { get; set; } = new() { EstimatedDelivery = DateTime.Today.AddDays(7) };
+
+    private string? errorMessage;
+    private string? successMessage;
+    private bool isSubmitting;
+
+    private async Task HandleSubmit()
+    {
+        isSubmitting = true;
+        errorMessage = null;
+        successMessage = null;
+
+        try
+        {
+            var response = await Http.PostAsJsonAsync("/api/shipments", model);
+            if (response.IsSuccessStatusCode)
+            {
+                var created = await response.Content.ReadFromJsonAsync<ShipmentDto>();
+                successMessage = $"Shipment created! Tracking number: {created?.TrackingNumber}";
+                model = new ShipmentDto { EstimatedDelivery = DateTime.Today.AddDays(7) };
+            }
+            else
+            {
+                errorMessage = "Failed to create shipment. Please try again.";
+            }
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Error creating shipment: {ex.Message}";
+        }
+        finally
+        {
+            isSubmitting = false;
+        }
+    }
+}
