 @page "/shipments"
 @rendermode InteractiveAuto
 @using Microsoft.AspNetCore.Authorization
 @attribute [Authorize(Roles = "Dispatcher")]
 @inject HttpClient Http
 @inject NavigationManager Navigation

 <PageTitle>Shipments Dashboard</PageTitle>

 <h3 class="mb-4">Shipments Dashboard</h3>

 <div class="mb-3">
     <button class="btn btn-primary" @onclick="NavigateToCreate">
         <span class="bi bi-plus-circle"></span> New Shipment
     </button>
 </div>

 @if (errorMessage is not null)
 {
     <div class="alert alert-danger">@errorMessage</div>
 }

 @if (shipments is null)
 {
     <p><em>Loading shipments...</em></p>
 }
 else if (shipments.Length == 0)
 {
     <p>No shipments found.</p>
 }
 else
 {
     <div class="table-responsive">
         <table class="table table-striped table-hover">
             <thead class="table-dark">
                 <tr>
                     <th>Tracking #</th>
                     <th>Origin</th>
                     <th>Destination</th>
                     <th>Status</th>
                     <th>Est. Delivery</th>
                     <th>Actions</th>
                 </tr>
             </thead>
             <tbody>
                 @foreach (var shipment in shipments)
                 {
                     <tr>
                         <td><code>@shipment.TrackingNumber</code></td>
                         <td>@shipment.Origin</td>
                         <td>@shipment.Destination</td>
                         <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                         <td>@shipment.EstimatedDelivery?.ToString("MMM dd, yyyy")</td>
                         <td>
                             <select class="form-select form-select-sm" style="width: auto; display: inline-block;"
                                     value="@shipment.Status"
                                     @onchange="(e) => UpdateStatus(shipment, e)">
                                 @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                 {
                                     <option value="@status">@status</option>
                                 }
                             </select>
                         </td>
                     </tr>
                 }
             </tbody>
         </table>
     </div>
 }

 @code {
     private ShipmentDto[]? shipments;
     private string? errorMessage;

     protected override async Task OnInitializedAsync()
     {
         await LoadShipments();
     }

     private async Task LoadShipments()
     {
         try
         {
             shipments = await Http.GetFromJsonAsync<ShipmentDto[]>("/api/shipments");
         }
         catch (Exception ex)
         {
             errorMessage = $"Failed to load shipments: {ex.Message}";
         }
     }

     private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
     {
         if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
         {
             try
             {
                 var update = new ShipmentDto { Status = newStatus };
                 var response = await Http.PutAsJsonAsync($"/api/shipments/{shipment.Id}", update);
                 if (response.IsSuccessStatusCode)
                 {
                     await LoadShipments();
                 }
                 else
                 {
                     errorMessage = "Failed to update shipment status.";
                 }
             }
             catch (Exception ex)
             {
                 errorMessage = $"Error updating status: {ex.Message}";
             }
         }
     }

     private void NavigateToCreate()
     {
         Navigation.NavigateTo("/create-shipment");
     }

     private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
     {
         ShipmentStatus.Pending => "bg-secondary",
         ShipmentStatus.PickedUp => "bg-info",
         ShipmentStatus.InTransit => "bg-primary",
         ShipmentStatus.OutForDelivery => "bg-warning text-dark",
         ShipmentStatus.Delivered => "bg-success",
         ShipmentStatus.Cancelled => "bg-danger",
         _ => "bg-secondary"
     };
 }

